            synonyms = "redemption, deliverance, rescue, regeneration, இரட்சிப்பு, விடுதலை",
            testamentFocus = "ALL",
            introductionEn = "Salvation is God's rescue plan for fallen humanity. Man is dead in trespasses and unable to save himself, but God in His boundless love sent His Son as the spotless Lamb.",
            introductionTa = "இரட்சிப்பு என்பது மனுக்குலத்தை மீட்டெடுக்கும் தேவனுடைய திட்டம். மனிதன் தன் சொந்தக் கிரியைகளால் தன்னை இரட்சிக்க முடியாது; கிருபையினாலே விசுவாசத்தைக் கொண்டு இரட்சிக்கப்படுகிறோம்.",
            detailedExplanationEn = "Salvation encompasses justification (saved from sin's penalty), sanctification (saved from sin's power), and glorification (saved from sin's presence in eternity). It is received purely by faith in Jesus Christ, not by human works (Ephesians 2:8-9).",
            detailedExplanationTa = "இரட்சிப்பு விசுவாசத்தினால் இலவசமாய் கிடைக்கிறது (எபேசியர் 2:8-9). கிறிஸ்து நமக்காக மரித்து உயிர்த்தெழுந்தார் என்று வாயினால் அறிக்கையிட்டு இருதயத்தில் விசுவாசித்தால் இரட்சிக்கப்படுவோம் (ரோமர் 10:9).",
            biblicalPeopleEn = "Zacchaeus, The Philippian Jailer, Cornelius, Nicodemus",
            biblicalPeopleTa = "சகேயு, பிலிப்பு சிறைச்சாலைக்காரன், கொர்நேலியு, நிக்கோதேமு",
            practicalApplicationsEn = "1. Confirm your personal salvation through faith in Christ.\n2. Walk worthy of the high calling of God.\n3. Share the Good News boldly with family and friends.\n4. Live with eternal joy knowing your name is written in heaven.",
            practicalApplicationsTa = "1. கிறிஸ்துவில் உங்கள் இரட்சிப்பின் நிச்சயத்தை உறுதி செய்யுங்கள்.\n2. இரட்சிப்புக்கு பாத்திரராய் பரிசுத்தமாய் வாழுங்கள்.\n3. சுவிசேஷத்தை மற்றவர்களுக்கு தைரியமாய் அறிவியுங்கள்.\n4. பரலோகத்தில் உங்கள் பெயர் எழுதப்பட்டிருப்பதற்காக மகிழுங்கள்.",
            commonMisunderstandingsEn = "Salvation cannot be earned by good deeds or religious rituals; good works are the fruit, not the root, of salvation.",
            commonMisunderstandingsTa = "இரட்சிப்பு நற்கிரியைகளால் சம்பாதிக்கப்படுவதல்ல; நற்கிரியைகள் இரட்சிப்பின் கனியாகும்.",
            keyLessonsEn = "Nor is there salvation in any other, for there is no other name under heaven given among men by which we must be saved (Acts 4:12).",
            keyLessonsTa = "வேறொருவராலும் இரட்சிப்பு இல்லை; நாம் இரட்சிக்கப்படுவதற்கு வானத்தின் கீழெங்கும் மனிதருக்குள்ளே அவருடைய நாமமேயன்றி வேறொரு நாமம் கட்டளையிடப்படவும் இல்லை.",
            status = "PUBLISHED",
            isFeatured = true,
