            category = "Doctrines & Truths",
            categoryTa = "உபதேசங்கள் & சத்தியங்கள்",
            keywords = "grace, favor, unmerited, mercy, suffiency, கிருபை, தயவு, இரக்கம்",
            synonyms = "favor, mercy, blessing, benevolence, கிருபை, தயவு",
            testamentFocus = "ALL",
            introductionEn = "Grace is God giving us what we could never earn or deserve. Through grace we are called, justified, sustained, and presented blameless before His holy throne.",
            introductionTa = "கிருபை என்பது நாம் சம்பாதிக்க முடியாத தேவ தயவாகும். கிருபையினாலே நாம் அழைக்கப்பட்டு, நீதிமான்களாக்கப்பட்டு, தினமும் அவருடைய பெலனால் காக்கப்படுகிறோம்.",
            detailedExplanationEn = "In the Old Covenant, grace was foreshadowed in the tabernacle and sacrifices. In the New Covenant, grace and truth came fully through Jesus Christ (John 1:17). God's grace is sufficient in every trial and weakness (2 Corinthians 12:9).",
            detailedExplanationTa = "பழைய ஏற்பாட்டில் கூடாரத்திலும் பலிகளிலும் நிழலாட்டமாய் இருந்த கிருபை, இயேசு கிறிஸ்துவினால் பூரணமாய் வெளிப்பட்டது (யோவான் 1:17). பலவீனத்தில் அவருடைய கிருபை பூரணமாய் விளங்கும்.",
            biblicalPeopleEn = "Paul (Thorn in the flesh), Mephibosheth, Noah, The Prodigal Son",
            biblicalPeopleTa = "பவுல், மேபிபோசேத், நோவா, காணாமற்போன குமாரன்",
            practicalApplicationsEn = "1. Approach the throne of grace boldly in times of need (Heb 4:16).\n2. Rest in Christ's finished work rather than self-righteous effort.\n3. Extend generous grace to imperfect people around you.\n4. Rely on His grace to overcome besetting habits.",
            practicalApplicationsTa = "1. சமயத்திற்கு ஏற்ற உதவிபெற கிருபாசனத்தண்டையில் தைரியமாய் வாருங்கள்.\n2. உங்கள் சொந்த நீதியை நம்பாமல் கிறிஸ்துவின் கிருபையைச் சாருங்கள்.\n3. மற்றவர்களுக்கும் கிருபையாய் மன்னியுங்கள்.\n4. பலவீனங்களை மேற்கொள்ள கிருபையை நாடுங்கள்.",
            commonMisunderstandingsEn = "Grace is not a license to indulge in sin; true grace teaches us to renounce ungodliness and live self-controlled lives (Titus 2:11-12).",
            commonMisunderstandingsTa = "கிருபை என்பது பாவத்தில் ஜீவிப்பதற்கான அனுமதியல்ல; அது அவபக்தியை விட்டு பரிசுத்தமாய் வாழப் போதிக்கிறது.",
            keyLessonsEn = "My grace is sufficient for thee: for my strength is made perfect in weakness (2 Cor 12:9).",
            keyLessonsTa = "என் கிருபை உனக்குப் போதும்; பலவீனத்திலே என் பலன் பூரணமாய் விளங்கும்.",
            status = "PUBLISHED",
            isFeatured = true,
            isPopular = false
