            keywords = "holy spirit, comforter, guide, counselor, fruit of spirit, gifts, பரிசுத்த ஆவி, தேற்றரவாளன்",
            synonyms = "Spirit of God, Comforter, Counselor, Paraclete, ஆவியானவர், தேற்றரவாளன்",
            testamentFocus = "ALL",
            introductionEn = "The Holy Spirit is not an impersonal force, but God Himself—the third Person of the Holy Trinity. He convicts of sin, regenerates the heart, seals the believer, and empowers for holy living and witness.",
            introductionTa = "பரிசுத்த ஆவியானவர் ஒரு சக்தியல்ல, அவர் திரித்துவத்தின் மூன்றாம் ஆளாகிய தேவன். அவர் பாவத்தைக் குறித்து உணர்த்தி, நம்மை மறுபடி பிறப்பித்து, கிறிஸ்துவுக்கு சாட்சியாக வாழ பெலனளிக்கிறார்.",
            detailedExplanationEn = "Jesus called Him the 'Paraclete'—the One called alongside to help. At Pentecost (Acts 2), the Spirit was poured out upon all believers, inaugurating the New Covenant community adorned with spiritual gifts and the fruit of the Spirit (Galatians 5:22-23).",
            detailedExplanationTa = "இயேசு அவரை தேற்றரவாளன் என்று அழைத்தார். பெந்தெகொஸ்தே நாளில் ஆவியானவர் ஊற்றப்பட்டு விசுவாசிகளுக்கு வரங்களையும், ஆவியின் கனியையும் அருளினார் (கலாத்தியர் 5:22-23).",
            biblicalPeopleEn = "The Apostles at Pentecost, Stephen, Philip, Bezalel, Gideon",
            biblicalPeopleTa = "பெந்தெகொஸ்தே அப்போஸ்தலர்கள், ஸ்தேவான், பிலிப்பு, பெசலெயேல், கிதியோன்",
            practicalApplicationsEn = "1. Do not grieve or quench the Holy Spirit by willful sin.\n2. Cultivate the fruit of the Spirit: love, joy, peace, longsuffering.\n3. Pray in the Spirit and seek His daily guidance.\n4. Rely on the Spirit's power to share Christ with boldness.",
            practicalApplicationsTa = "1. பாவத்தினால் பரிசுத்த ஆவியானவரைத் துக்கப்படுத்தாதீர்கள்.\n2. ஆவியின் கனிகளாகிய அன்பு, சந்தோஷம், சமாதானத்தை வளருங்கள்.\n3. ஆவியிலே ஜெபித்து அவருடைய வழிநடத்துதலைப் பின்பற்றுங்கள்.\n4. சாட்சியிட ஆவியின் வல்லமையை நாடுங்கள்.",
            commonMisunderstandingsEn = "The Holy Spirit does not draw attention to Himself; His primary mission is to glorify Jesus Christ and testify of Him (John 16:14).",
            commonMisunderstandingsTa = "ஆவியானவர் தம்மை முன்னிறுத்தாமல், இயேசு கிறிஸ்துவை மகிமைப்படுத்தி சாட்சியிடுகிறார்.",
            keyLessonsEn = "Ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me (Acts 1:8).",
            keyLessonsTa = "பரிசுத்த ஆவி உங்களிடத்தில் வரும்போது நீங்கள் பெலனடைந்து, எனக்குச் சாட்சிகளாயிருப்பீர்கள்.",
            status = "PUBLISHED",
            isFeatured = true,
            isPopular = true
