            detailedExplanationEn = "Whoever believes on the Son has everlasting life (John 3:36). This life begins the moment one trusts Christ and culminates in eternal presence before God's throne where death, sorrow, and pain exist no more.",
            detailedExplanationTa = "குமாரனிடத்தில் விசுவாசமாயிருக்கிறவனுக்கு நித்திய ஜீவன் உண்டு (யோவான் 3:36). விசுவாசிக்கும் நொடியிலேயே தொடங்கும் இந்த ஜீவன், பரலோகத்தில் மரணமும் கண்ணீரும் இல்லாத நித்திய வாழ்வாக மலர்கிறது.",
            biblicalPeopleEn = "Lazarus and the rich man, Stephen beholding Christ, The thief on the cross",
            biblicalPeopleTa = "லாசரு, ஸ்தேவான், சிலுவையில் மனந்திரும்பிய கள்ளன்",
            practicalApplicationsEn = "1. Rest in the blessed assurance that your salvation is eternally secure in Christ.\n2. Live with an eternal perspective, investing in treasures in heaven.\n3. Proclaim the Gospel so that others may receive eternal life.",
            practicalApplicationsTa = "1. கிறிஸ்துவில் உங்கள் நித்திய வாழ்வின் நிச்சயத்தில் மகிழுங்கள்.\n2. பரலோக பொக்கிஷங்களைச் சேர்த்து வைக்கும்படி உங்கள் வாழ்க்கையை முதலீடு செய்யுங்கள்.\n3. பிறரும் நித்திய வாழ்வைப் பெறும்படி சுவிசேஷத்தை அறிவியுங்கள்.",
            commonMisunderstandingsEn = "Eternal life is not earned upon physical death; it is the present possession of every true believer in Christ.",
            commonMisunderstandingsTa = "நித்திய ஜீவன் என்பது மரணத்திற்குப் பின் கிடைக்கும் ஒன்றல்ல; அது இப்போதே விசுவாசிகளுக்குள் வாசம் செய்கிறது.",
